{
  "name": "ai",
  "compatibility_date": "2026-07-17",
  "compatibility_flags": [
    "nodejs_compat",
    "nodejs_als"
  ],
  "main": "./worker/entrypoint.ts",
  "observability": {
    "enabled": true,
    "head_sampling_rate": 1,
    "logs": {
      "enabled": true,
      "head_sampling_rate": 1,
      "persist": true,
      "invocation_logs": true
    },
    "traces": {
      "enabled": true,
      "persist": true,
      "head_sampling_rate": 1
    }
  },
  "assets": {
    "directory": "./dist",
    "binding": "ASSETS"
  },
  "kv_namespaces": [
    {
      "binding": "CACHE",
      "id": "b5d6927aea7345efaddf56bcc2878e89"
    }
  ],
  "d1_databases": [
    {
      "binding": "DB",
      "database_name": "umuo-content",
      "database_id": "3d229c09-2965-4dbd-a17d-b4e43b15c86d",
      "migrations_dir": "./db/migrations"
    }
  ],
  "triggers": {
    "crons": [
      "*/15 * * * *",
      "17 3 * * *"
    ]
  },
  "account_id": "adec54ff48f1c2618cf92f2279377392"
}
